window.PLACES = [{"id":"cons","main":1,"cat":"arch","e":"🎻","name":"Саратовская консерватория","short":"Неоготика · 1912","c":[46.034258,51.529797],"z":16.9,"p":66,"b":-150,"tags":["1912","Архитектура","Музыка"],"img":"Konserv saratov.JPG","text":["Перед вами главный символ Саратова — консерватория имени Леонида Собинова.","Она открылась в 1912 году и стала третьей консерваторией в России — после петербургской и московской.","Здание построили в 1902 году для музыкального училища, а спустя десять лет архитектор Семён Каллистратов превратил его в сказочный готический замок со шпилями, башенками и химерами.","В Большом зале звучит старинный немецкий орган, а летними вечерами музыку слышно прямо на улице."],"facts":[["№ 3","консерватория России"],["1912","год открытия"],["1935","имя Собинова"]],"au":{"t":[0.0,3.19,8.88,16.75,29.26],"d":36.07,"v":"f80ab2b712"}},{"id":"prosp","main":1,"cat":"arch","e":"🚶","name":"Проспект Столыпина","short":"Саратовский Арбат","c":[46.027806,51.531417],"z":16.2,"p":68,"b":118,"tags":["XIX век","Пешеходная улица"],"img":"Stolypin Avenue in Saratov (July 2025) - 0 2.jpg","text":["Это проспект Столыпина — пешеходное сердце города, которое саратовцы по привычке называют просто «проспект».","Когда-то улица называлась Немецкой: здесь селились колонисты, приглашённые в Поволжье Екатериной Второй.","В 1985 году она стала одной из первых пешеходных улиц в стране — раньше московского Арбата.","Прогуляйтесь по ней не спеша: почти у каждого дома здесь своя история."],"facts":[["≈ 1 км","длина прогулки"],["1985","стала пешеходной"],["2022","новое имя"]],"au":{"t":[0.0,2.57,10.56,17.83,25.97],"d":31.34,"v":"3f75c41f5d"}},{"id":"lipki","main":1,"cat":"park","e":"🌳","name":"Сад «Липки»","short":"Старейший сад · 1824","c":[46.03722,51.52889],"z":16.6,"p":62,"b":-40,"tags":["1824","Парк"],"img":"Саратов Липки 1.jpg","text":["Рядом с консерваторией шумит листвой сад «Липки» — зелёная гостиная старого Саратова.","Его заложили в 1824 году как городской бульвар, высадив сотни молодых лип — отсюда и название.","Сад окружён ажурной чугунной оградой, а на его аллеях растёт несколько десятков пород деревьев и кустарников.","Здесь назначают свидания уже двести лет подряд."],"facts":[["200 лет","истории сада"],["1824","год основания"],["🌿","памятник природы"]],"au":{"t":[0.0,2.06,8.52,17.04,24.58],"d":28.82,"v":"9b88d9de4f"}},{"id":"utoli","main":1,"cat":"temple","e":"⛪","name":"Храм «Утоли моя печали»","short":"Сказочные купола · 1906","c":[46.035778,51.530219],"z":17.1,"p":66,"b":60,"tags":["1906","Храм"],"img":"Саратов православный храм Утоли моя печали.jpg","text":["Этот нарядный храм с разноцветными куполами напоминает московский собор Василия Блаженного в миниатюре.","Его построил в 1906 году архитектор Пётр Зыбин как домовую церковь архиерейского подворья.","В советские годы храм уцелел благодаря необычной судьбе: несколько десятилетий в нём работал городской планетарий.","Сегодня это одна из самых фотографируемых точек Саратова."],"facts":[["1906","год постройки"],["🔭","был планетарием"],["П. Зыбин","архитектор"]],"au":{"t":[0.0,2.9,9.67,17.18,24.77],"d":29.47,"v":"f5cdee0a24"}},{"id":"rad","main":1,"cat":"culture","e":"🖼️","name":"Радищевский музей","short":"Первый музей провинции","c":[46.03525,51.532194],"z":16.8,"p":64,"b":-110,"tags":["1885","Музей"],"img":"Радищевский музей летом.jpg","text":["Радищевский музей — первый общедоступный художественный музей российской провинции.","Он открылся в 1885 году — раньше Русского музея в Петербурге.","Музей основал художник-маринист Алексей Боголюбов и назвал его в честь своего деда — писателя Александра Радищева.","В залах можно увидеть работы Репина, Шишкина, Борисова-Мусатова, Коро и скульптуры Родена."],"facts":[["1885","год открытия"],["№ 1","музей в провинции"],["30 000+","экспонатов"]],"au":{"t":[0.0,2.54,8.59,14.86,22.97],"d":29.88,"v":"42f5bac6cb"}},{"id":"opera","main":1,"cat":"culture","e":"🎭","name":"Театр оперы и балета","short":"Театральная площадь","c":[46.0321,51.532881],"z":16.6,"p":64,"b":30,"tags":["с 1803","Театр"],"img":"Театр оперы и балета.jpg","text":["На Театральной площади стоит академический театр оперы и балета — гордость музыкального Саратова.","Театральная история города началась ещё в 1803 году, а каменное здание театра появилось здесь в 1865 году.","Каждую весну театр проводит Собиновский музыкальный фестиваль, на который съезжаются артисты со всей страны.","Площадь перед театром — главное место городских праздников."],"facts":[["1803","начало истории"],["1865","каменное здание"],["🎶","Собиновский фестиваль"]],"au":{"t":[0.0,2.9,9.77,19.25,26.57],"d":31.25,"v":"c177a7f24a"}},{"id":"market","main":1,"cat":"arch","e":"🍉","name":"Крытый рынок","short":"Модерн · 1916","c":[46.02025,51.532111],"z":16.6,"p":64,"b":-70,"tags":["1916","Архитектура"],"img":"Market Building in Saratov (July 2025).jpg","text":["Крытый рынок — памятник эпохи модерна и один из первых крытых рынков России.","Его построили в 1916 году по проекту архитектора Василия Люкшина.","Внутри — огромный торговый зал под стеклянным световым фонарём и фонтан в самом центре.","Уже больше ста лет сюда приходят за волжской рыбой, фруктами и знаменитым саратовским калачом."],"facts":[["1916","год открытия"],["100+ лет","торговли"],["⛲","фонтан внутри"]],"au":{"t":[0.0,2.16,7.97,14.11,20.47],"d":27.07,"v":"813e1fc253"}},{"id":"circus","main":1,"cat":"culture","e":"🎪","name":"Цирк братьев Никитиных","short":"Старейший цирк России","c":[46.021194,51.534],"z":16.6,"p":64,"b":150,"tags":["с 1870-х","Цирк"],"img":"Саратовский цирк имени братьев Никитиных.jpg","text":["Саратовский цирк носит имя братьев Никитиных — основателей русского национального цирка.","Он ведёт историю с семидесятых годов девятнадцатого века и считается одним из старейших стационарных цирков страны.","На этом манеже начинал свой путь легендарный «солнечный клоун» Олег Попов.","Нынешнее здание с куполом появилось в 1931 году, а в сквере у входа стоит бронзовый памятник самим братьям."],"facts":[["1870-е","начало истории"],["1931","здание с куполом"],["🤡","манеж Олега Попова"]],"au":{"t":[0.0,2.9,9.34,16.82,22.78],"d":31.18,"v":"7fcc52b994"}},{"id":"sgu","main":1,"cat":"arch","e":"🎓","name":"Саратовский университет","short":"Основан в 1909 году","c":[46.007972,51.53875],"z":16.2,"p":64,"b":-20,"tags":["1909","Наука"],"img":"Univer saratov.JPG","text":["Саратовский университет открылся в 1909 году как Императорский Николаевский — последний классический университет Российской империи.","Саратов выбрали во многом благодаря Петру Столыпину, который помнил город по годам своего губернаторства.","Стройный ансамбль корпусов в стиле неоклассицизма создал архитектор Карл Мюфке.","Здесь работали генетик Николай Вавилов и хирург Василий Разумовский — первый ректор университета."],"facts":[["1909","год открытия"],["№ 10","в империи"],["К. Мюфке","архитектор"]],"au":{"t":[0.0,3.1,12.41,19.44,25.32],"d":32.28,"v":"77453faa3c"}},{"id":"park","main":1,"cat":"park","e":"🦆","name":"Городской парк","short":"Дубрава и пруды","c":[45.998889,51.518056],"z":15.6,"p":62,"b":70,"tags":["XIX век","Парк"],"img":"Saratov City Park (July 2025) - 0 3.jpg","text":["Городской парк — настоящая дубрава посреди большого города.","По преданию, дубы здесь высадили пленные французы после войны 1812 года на даче губернатора Алексея Панчулидзева.","Сегодня некоторым деревьям больше двухсот лет.","В парке — каскад прудов с лебедями и утками, лодочная станция и ручные белки, которые берут орехи прямо из рук."],"facts":[["200 лет","старым дубам"],["🦢","каскад прудов"],["🐿","ручные белки"]],"au":{"t":[0.0,2.26,7.25,16.03,19.94],"d":28.34,"v":"5b3f7adb2c"}},{"id":"troitsky","main":1,"cat":"temple","e":"🔔","name":"Троицкий собор","short":"Старейшее здание · XVII век","c":[46.05556,51.52806],"z":16.8,"p":64,"b":-130,"tags":["1695","Храм"],"img":"Свято-Троицкий собор (Саратов).jpg","text":["Троицкий собор — самое старое здание Саратова.","Его возвели в конце семнадцатого века в стиле московского барокко.","Собор пережил пожары, перестройки и смену эпох, а его колокольня слегка наклонена — словно саратовская Пизанская башня.","Вокруг — Музейная площадь, с которой начинался правобережный город."],"facts":[["1695","год завершения"],["330 лет","над Волгой"],["🏛","Музейная площадь"]],"au":{"t":[0.0,2.3,6.46,11.33,20.06],"d":25.56,"v":"7b06fac1db"}},{"id":"nab","main":1,"cat":"park","e":"🚀","name":"Набережная Космонавтов","short":"Променад у Волги","c":[46.04861,51.52556],"z":15.8,"p":66,"b":-60,"tags":["1962","Волга"],"img":"Naberezhnaya Kosmonavtov in Saratov (July 2025) - 0 2.jpg","text":["Набережная Космонавтов тянется вдоль Волги и ярусами спускается к самой воде.","Своё имя она получила в 1962 году — в честь Юрия Гагарина, который учился в Саратове и приземлился на саратовской земле.","От причалов уходят прогулочные теплоходы, а вечером отсюда открывается лучший вид на огни моста и Энгельса на другом берегу."],"facts":[["1962","получила имя"],["4 яруса","спуск к Волге"],["🚢","прогулки по Волге"]],"au":{"t":[0.0,2.86,8.57,17.93],"d":26.35,"v":"3accfe003d"}},{"id":"bridge","main":1,"cat":"arch","e":"🌉","name":"Саратовский мост","short":"2,8 км через Волгу","c":[46.07056,51.51722],"z":13.9,"p":68,"b":-55,"tags":["1965","Волга"],"img":"Saratov Bridge (July 2025) - 0 10.jpg","text":["Саратовский мост соединяет Саратов с городом Энгельсом на левом берегу Волги.","Когда его открыли в 1965 году, это был самый длинный мост в Европе — две тысячи восемьсот метров.","Его изящный силуэт стал такой же визитной карточкой города, как и консерватория.","Под мостом лежат волжские острова с песчаными пляжами, куда горожане летом спускаются прямо по лестницам с моста."],"facts":[["2 804 м","длина моста"],["1965","год открытия"],["№ 1","в Европе тогда"]],"au":{"t":[0.0,2.47,8.02,16.2,22.34],"d":30.07,"v":"f636d660ee"}},{"id":"cranes","main":1,"cat":"mon","e":"🕊️","name":"«Журавли» и Парк Победы","short":"Соколовая гора","c":[46.049599,51.544275],"z":15.3,"p":70,"b":160,"tags":["1982","Мемориал","Панорама"],"img":"Saratov, Victory Park, Мемориал Журавли - panoramio (1).jpg","text":["Мы поднялись на Соколовую гору — самую знаменитую смотровую площадку Саратова.","Мемориал «Журавли» высотой сорок метров открыли в 1982 году в память о саратовцах, не вернувшихся с Великой Отечественной войны.","Двенадцать серебристых журавлей летят на запад — туда, где шли бои.","Вокруг раскинулся Парк Победы с музеем военной техники под открытым небом.","Отсюда виден весь город, Волга и мост как на ладони."],"facts":[["40 м","высота мемориала"],["12","журавлей"],["1982","год открытия"]],"au":{"t":[0.0,2.98,8.86,19.03,24.31,29.83],"d":34.42,"v":"25f9210d65"}},{"id":"gagarin","main":1,"far":1,"cat":"event","e":"👨‍🚀","name":"Место приземления Гагарина","short":"12 апреля 1961 · 30 км от города","c":[45.99754,51.270834],"z":14.2,"p":64,"b":20,"tags":["12.04.1961","Космос","Событие"],"img":"Gagarin field.jpg","text":["А теперь — перелёт за город, на Гагаринское поле.","Именно здесь, у деревни Смеловка, 12 апреля 1961 года приземлился Юрий Гагарин, совершив первый в истории полёт человека в космос.","Полёт длился сто восемь минут.","Саратовская земля дважды стала для него стартовой: в Саратове он окончил индустриальный техникум и впервые поднялся в небо в местном аэроклубе.","Сегодня на поле — Парк покорителей космоса, стела в виде взлетающей ракеты и галерея космонавтики."],"facts":[["108 мин","первый полёт"],["1961","12 апреля"],["🚀","Парк покорителей космоса"]],"au":{"t":[0.0,3.05,7.37,18.0,21.24,30.34],"d":37.44,"v":"6af8b4fef6"}},{"id":"astoria","cat":"arch","e":"🏨","name":"Гостиница «Астория»","short":"Замок на проспекте · 1917","c":[46.026619,51.531897],"tags":["1917","Модерн"],"img":"Кирова пр-т., 34.JPG","text":["Гостиница «Астория» — один из архитектурных символов Саратова.","Её построили в 1917 году, и своими башенками, эркерами и скульптурами на фасаде она похожа на европейский замок.","С 1956 года гостиница называется «Волга», но старое имя саратовцы помнят до сих пор."],"au":{"t":[0.0,2.86,8.4,17.69],"d":25.66,"v":"63f8375a1c"}},{"id":"birzha","cat":"arch","e":"🏛️","name":"Купеческая биржа","short":"Хлебная столица Поволжья","c":[46.036611,51.533194],"tags":["XIX век","Классицизм"],"img":"Здание биржи (вид с востока) Саратов.jpg","text":["Здание купеческой биржи построили в конце девятнадцатого века по проекту архитектора Франца Шустера.","Здесь заключали сделки саратовские хлеботорговцы — в те годы город был одной из мукомольных столиц России.","Сегодня в бывшей бирже размещается один из корпусов Радищевского музея."],"au":{"t":[0.0,2.45,9.26,16.66],"d":22.15,"v":"2d05c8ca2e"}},{"id":"skvortsov","cat":"arch","e":"🦁","name":"Особняк Скворцова","short":"Модерн со сфинксом","c":[46.040806,51.529944],"tags":["Начало XX века","Модерн"],"img":"Особняк Скворцова АИ.jpg","text":["Этот особняк в стиле модерн построил в начале двадцатого века адвокат Александр Скворцов — один из директоров музыкального училища и консерватории.","Фасад облицован глазурованной плиткой, а со стены на прохожих смотрит загадочная голова сфинкса.","Сам хозяин с семьёй жил на втором этаже, а первый сдавал состоятельным квартирантам."],"au":{"t":[0.0,2.62,12.24,19.06],"d":25.25,"v":"fb96c09228"}},{"id":"melnitsa","cat":"arch","e":"🏭","name":"Мельница Шмидта","short":"Красный кирпич мукомолов","c":[46.011139,51.51652],"tags":["XIX век","Промышленная архитектура"],"img":"Малая мельница Шмидта в Саратове.jpg","text":["Ансамбль из красного кирпича, похожий на рыцарскую крепость, — это паровая мельница братьев Шмидт.","Шмидты, выходцы из поволжских немцев, были настоящими мучными королями: саратовскую муку высшего сорта знали по всей России и в Европе.","Таких мельниц-замков вдоль Волги стояло несколько, и они до сих пор определяют силуэт старого Саратова."],"au":{"t":[0.0,2.42,9.5,18.98],"d":26.14,"v":"0c95460999"}},{"id":"garage","cat":"arch","e":"🚗","name":"Автогараж Соколова и Иванова","short":"Дом с автомобилем","c":[46.02444,51.536356],"tags":["Начало XX века","Курьёз"],"img":"Автогараж и магазин Соколова С.И., Иванова З.И.(Саратов).JPG","text":["Поднимите глаза: под крышей этого дома едет старинный автомобиль.","Барельеф напоминает, что в начале двадцатого века здесь работали гараж и магазин Соколова и Иванова — одни из первых в городе, кто торговал диковинными тогда «моторами».","Это, пожалуй, самая старая автомобильная реклама Саратова."],"au":{"t":[0.0,3.43,8.45,19.75],"d":24.79,"v":"794f794b87"}},{"id":"nikitin_house","cat":"people","e":"🎩","name":"Дом Никитина","short":"Особняк циркового короля","c":[46.023958,51.532069],"tags":["Личность","Проспект"],"img":null,"text":["Этот дом на углу проспекта и Вольской улицы принадлежал Петру Никитину — младшему из трёх братьев, создавших русский национальный цирк.","Братья Никитины родились в семье крепостного шарманщика и начинали бродячими артистами.","Пётр был атлетом, гимнастом и шпагоглотателем, а разбогатев, остался жить в Саратове — городе, где начиналось их цирковое дело."],"au":{"t":[0.0,2.3,11.18,17.78],"d":26.93,"v":"97e8617d7a"}},{"id":"vokzal","cat":"arch","e":"🚂","name":"Вокзал Саратов-1","short":"Железная дорога с 1871 года","c":[45.99861,51.54194],"tags":["1871","Транспорт"],"img":"Станция Саратов (вокзал, переход).jpg","text":["Железная дорога пришла в Саратов в 1871 году и превратила его в крупнейший торговый город Поволжья.","На привокзальной площади стоит памятник Дзержинскому с любопытной историей: его поставили на гранитный постамент, оставшийся от снесённого памятника императору Александру Второму."],"au":{"t":[0.0,2.81,10.87],"d":22.2,"v":"cc801434d1"}},{"id":"rechnoy","cat":"arch","e":"⚓","name":"Речной вокзал","short":"Ворота города с Волги","c":[46.055194,51.526139],"tags":["Волга","Транспорт"],"img":"Саратовский речной вокзал - panoramio.jpg","text":["Речной вокзал — волжские ворота Саратова.","Отсюда отправляются круизные теплоходы до Астрахани, Казани и Москвы, а летом — прогулочные катера и «омики» на острова.","Сто лет назад у этого берега теснились десятки пристаней пароходных обществ «Самолёт», «Кавказ и Меркурий» и «По Волге»."],"au":{"t":[0.0,2.23,6.07,15.5],"d":24.62,"v":"97d6c77334"}},{"id":"gymnasium","cat":"people","e":"📚","name":"Первая мужская гимназия","short":"Школа Чернышевского и Яблочкова","c":[46.0397,51.5271],"tags":["Личности","Образование"],"img":"1 muzhskaya gimnaziya in Saratov.jpg","text":["Первая мужская гимназия была главной школой дореволюционного Саратова.","Николай Чернышевский здесь преподавал словесность, а среди гимназистов в разные годы были изобретатель Павел Яблочков и актёр Борис Бабочкин — будущий Чапаев советского кино."],"au":{"t":[0.0,3.1,8.21],"d":19.39,"v":"38c0536701"}},{"id":"bogolubov","cat":"people","e":"🎨","name":"Боголюбовское училище","short":"Колыбель саратовской школы живописи","c":[46.00625,51.54125],"tags":["1897","Художники"],"img":"Саратовское художественное училище им Боголюбова АП.jpg","text":["Боголюбовское рисовальное училище открылось в 1897 году при Радищевском музее.","Из его стен вышли художники Павел Кузнецов и Пётр Уткин и скульптор Александр Матвеев — мастера, прославившие саратовскую школу на весь мир.","Училище носит имя Алексея Боголюбова, подарившего городу музей."],"au":{"t":[0.0,2.88,10.15,19.9],"d":25.18,"v":"00e2b20548"}},{"id":"drama","cat":"culture","e":"🎭","name":"Театр драмы имени Слонова","short":"Один из старейших театров России","c":[46.001667,51.533889],"tags":["1803","Театр"],"img":"Саратов театр драмы 9 мая.jpg","text":["Саратовский театр драмы основан в 1803 году и считается одним из старейших в России.","Он носит имя актёра и режиссёра Ивана Слонова.","На этой сцене восемь лет играл молодой Олег Янковский — отсюда его и позвали в московский «Ленком»."],"au":{"t":[0.0,3.17,10.08,14.3],"d":21.67,"v":"d62c02d8a5"}},{"id":"tuz","cat":"culture","e":"🧸","name":"Саратовский ТЮЗ","short":"Первый в мире театр для детей","c":[46.02389,51.53472],"tags":["1918","Театр"],"img":"Вольская улица ТЮЗ.jpg","text":["Саратовский театр юного зрителя — первый в мире профессиональный театр для детей.","Он открылся 4 октября 1918 года, в разгар Гражданской войны.","Больше полувека театром руководил режиссёр Юрий Киселёв, чьё имя ТЮЗ носит сегодня."],"au":{"t":[0.0,2.45,8.45,15.19],"d":21.84,"v":"b1422f219d"}},{"id":"teremok","cat":"culture","e":"🪆","name":"Театр кукол «Теремок»","short":"Один из первых в стране · 1936","c":[46.03833,51.52583],"tags":["1936","Театр"],"img":"Театр кукол Теремок Саратов.jpg","text":["Театр кукол «Теремок» основан в 1936 году и стал одним из первых кукольных театров России.","На его спектаклях выросло не одно поколение саратовцев, а сам театр давно играет не только для детей, но и для взрослых."],"au":{"t":[0.0,2.76,10.87],"d":18.91,"v":"3ce0f07430"}},{"id":"planetarium","cat":"culture","e":"🔭","name":"Саратовский планетарий","short":"Звёзды над Волгой","c":[46.040528,51.52556],"tags":["Наука","Космос"],"img":"Планетарий Саратов.jpg","text":["Саратовский планетарий долгие годы работал под куполом храма «Утоли моя печали», а потом переехал сюда, на улицу Чернышевского.","В городе, где учился летать Гагарин, интерес к звёздам — дело почти семейное."],"au":{"t":[0.0,2.83,11.74],"d":18.0,"v":"93d6b43b94"}},{"id":"museum_kraeved","cat":"culture","e":"🏺","name":"Музей краеведения","short":"Особняк на Музейной площади","c":[46.05583,51.5275],"tags":["Музей","История края"],"img":"Вид с главного входа.jpg","text":["Областной музей краеведения занимает старинный особняк с колоннами на Музейной площади.","В его залах — вся история края: от бивней мамонта и сарматских мечей до самолёта Як-18, на котором учился летать Юрий Гагарин.","Отдельная экспозиция рассказывает о немцах Поволжья."],"au":{"t":[0.0,2.88,8.76,18.31],"d":22.75,"v":"9d7f5c6981"}},{"id":"nat_village","cat":"culture","e":"🛖","name":"Национальная деревня","short":"Подворья народов области","c":[46.061583,51.541278],"tags":["Этнография","Парк Победы"],"img":"Знак дружбы народов в парке Победы (Саратов).jpg","text":["Национальная деревня — музей под открытым небом в Парке Победы.","Русская изба, украинская хата, немецкий дом, казахская юрта, татарское и армянское подворья стоят здесь на одной улице.","В Саратовской области живут люди более ста тридцати национальностей, и деревня задумана как образ этого большого общего дома."],"au":{"t":[0.0,2.71,7.73,16.9],"d":25.1,"v":"8d3f7c706c"}},{"id":"war_museum","cat":"culture","e":"🛩️","name":"Музей боевой славы","short":"Техника под открытым небом","c":[46.0537,51.5435],"tags":["Музей","Парк Победы"],"img":"Музей боевой и трудовой славы Парк Победы Саратов.jpg","text":["На склонах Соколовой горы собрана одна из самых больших в стране коллекций военной техники под открытым небом.","Танки, самолёты, вертолёты, корабельные орудия и даже целый поезд — почти ко всему можно подойти вплотную.","Саратов в годы войны был городом-арсеналом: здесь выпустили больше тринадцати тысяч истребителей Як."],"au":{"t":[0.0,2.62,9.79,10.03],"d":17.11,"v":"43dcff291d"}},{"id":"chern_house","cat":"people","e":"✒️","name":"Музей-усадьба Чернышевского","short":"Здесь родился автор «Что делать?»","c":[46.041083,51.524889],"tags":["1828","Писатель"],"img":"Saratov dom muzey Chernishevskogo.JPG","text":["В этой усадьбе над Волгой в 1828 году родился Николай Чернышевский — писатель, философ и автор романа «Что делать?».","Здесь он прожил в общей сложности больше двадцати лет и сюда же вернулся умирать после каторги и ссылки.","Музей открылся в 1920 году, и в нём сохранились подлинные вещи семьи."],"au":{"t":[0.0,3.07,12.67,19.7],"d":26.3,"v":"63309f229f"}},{"id":"chern_mon","cat":"people","e":"🗿","name":"Памятник Чернышевскому","short":"На месте царя-освободителя","c":[46.03528,51.529806],"tags":["1953","Памятник"],"img":null,"text":["Бронзовый Чернышевский стоит у входа в «Липки» с 1953 года; его автор — скульптор Александр Кибальников.","До революции на этом самом месте стоял памятник императору Александру Второму, поставленный на народные пожертвования.","Царя сняли, а на его гранитном постаменте позже оказался Дзержинский у вокзала."],"au":{"t":[0.0,2.83,12.1,20.11],"d":26.06,"v":"da73356034"}},{"id":"musatov","cat":"people","e":"🌸","name":"Дом-музей Борисова-Мусатова","short":"Флигель художника-мечтателя","c":[46.019206,51.524292],"tags":["Художник","Музей"],"img":"Muzei usad`ba borisova musatova.jpg","text":["В этом скромном флигеле с садом жил и работал Виктор Борисов-Мусатов — один из самых поэтичных русских художников.","Он родился в Саратове в 1870 году, и именно здесь, в саду, писал своих задумчивых дам в старинных платьях.","Его картины «Водоём» и «Призраки» сегодня хранятся в Третьяковской галерее."],"au":{"t":[0.0,3.17,11.21,20.33],"d":26.88,"v":"9a02dfbe5c"}},{"id":"kuznetsov","cat":"people","e":"🖌️","name":"Дом Павла Кузнецова","short":"Родина «Голубой розы»","c":[46.04833,51.53389],"tags":["1878","Художник"],"img":"Место рождения и первых лет жизни П.В.Кузнецова.jpg","text":["В этом доме у Глебучева оврага в 1878 году родился живописец Павел Кузнецов.","Сын иконописца, он стал одним из основателей знаменитого объединения «Голубая роза» и прославился степными и восточными циклами.","Музей в доме художника открылся только через двадцать лет после его смерти — стараниями саратовских энтузиастов."],"au":{"t":[0.0,2.81,10.01,19.46],"d":27.07,"v":"99f4779528"}},{"id":"fedin","cat":"people","e":"📖","name":"Музей Константина Федина","short":"Школа будущего писателя","c":[46.04556,51.526333],"tags":["XVIII век","Писатель"],"img":"Музей Федина и цветник во дворе Саратов.jpg","text":["Музей писателя Константина Федина расположен в одном из старейших зданий города — оно построено ещё в восемнадцатом веке.","Когда-то здесь было Сретенское начальное училище, где маленький Костя Федин учился на рубеже веков.","Саратов своего детства он описал в романах «Первые радости» и «Необыкновенное лето».","Рядом, на набережной, стоит памятник писателю."],"au":{"t":[0.0,3.0,11.18,18.05,25.03],"d":29.54,"v":"d5d4b56dd3"}},{"id":"stolypin","cat":"people","e":"🎖️","name":"Памятник Столыпину","short":"Губернатор Саратова в 1903–1906","c":[46.03639,51.53167],"tags":["2002","Личность"],"img":"Дом Бендера и памятник Столыпину П А.jpg","text":["Пётр Столыпин был саратовским губернатором с 1903 по 1906 год — отсюда он уехал в Петербург, чтобы стать министром и главой правительства.","При нём в Саратове заасфальтировали центральные улицы, провели газовое освещение и обновили телефонную сеть.","Памятник открыли в 2002 году; у ног реформатора — четыре фигуры: пахарь, кузнец, священник и воин."],"au":{"t":[0.0,2.54,13.73,21.38],"d":29.83,"v":"832f2a54d9"}},{"id":"technikum","cat":"people","e":"🛠️","name":"Техникум Гагарина","short":"Здесь учился первый космонавт","c":[46.03194,51.52833],"tags":["1951–1955","Гагарин"],"img":"Колледж имени Гагарина главный вход Саратов.jpg","text":["В этом здании с 1951 по 1955 год учился Юрий Гагарин — тогда оно называлось Саратовским индустриальным техникумом.","Будущий космонавт получил здесь диплом с отличием по специальности «литейное производство».","В колледже работает народный музей Гагарина, где хранят его учебные вещи и документы."],"au":{"t":[0.0,2.54,13.06,19.73],"d":26.09,"v":"b760ced39d"}},{"id":"aeroclub","cat":"people","e":"🛫","name":"Здание аэроклуба","short":"Отсюда Гагарин шагнул в небо","c":[46.021716,51.525472],"tags":["Модерн","Гагарин"],"img":"Здание аэроклуба ул Рабочая 22.jpg","text":["В этом особняке в стиле модерн размещался Саратовский аэроклуб.","Студент техникума Юрий Гагарин записался сюда в 1954 году, а через год совершил первый самостоятельный полёт.","Именно в Саратове он понял, что его призвание — небо."],"au":{"t":[0.0,2.93,8.09,17.21],"d":21.86,"v":"900c7e4d9f"}},{"id":"gagarin_mon","cat":"people","e":"🧑‍🚀","name":"Памятник Гагарину","short":"Шагает по набережной","c":[46.051836,51.525849],"tags":["1995","Гагарин"],"img":null,"text":["Бронзовый Гагарин идёт по набережной, названной в честь космонавтов.","У памятника непростая судьба: его отлили в 1990 году, но у города не нашлось денег, и скульптура несколько лет ждала своего часа на заводе.","Установили её только в 1995 году."],"au":{"t":[0.0,2.52,7.97,18.17],"d":22.66,"v":"483fb2ed83"}},{"id":"vavilov","cat":"people","e":"🌾","name":"Памятник Николаю Вавилову","short":"Гений и трагедия","c":[46.01799,51.53314],"tags":["Учёный","Генетика"],"img":null,"text":["Николай Вавилов приехал в Саратов в 1917 году молодым профессором и провёл здесь четыре самых плодотворных года.","С Саратовом связана и его гибель: великий генетик, мечтавший накормить человечество, умер от истощения в саратовской тюрьме в январе 1943 года.","Памятник стоит на улице, которая носит его имя."],"au":{"t":[0.0,2.93,11.47,22.39],"d":26.86,"v":"9a0c51c046"}},{"id":"vavilov_law","cat":"event","e":"🧬","name":"1920: закон Вавилова","short":"«Биологи приветствуют своего Менделеева»","c":[46.03472,51.531056],"tags":["1920","Событие","Наука"],"img":null,"text":["Четвёртого июня 1920 года в Саратове на съезде селекционеров Николай Вавилов впервые изложил закон гомологических рядов.","Зал встал и аплодировал, а один из профессоров сказал: «Это биологи приветствуют своего Менделеева».","Закон позволил предсказывать ещё не открытые формы растений — так же, как таблица Менделеева предсказывала элементы."],"au":{"t":[0.0,3.82,12.82,19.87],"d":27.91,"v":"d99d886c3d"}},{"id":"cemetery","cat":"people","e":"🕯️","name":"Воскресенское кладбище","short":"Некрополь великих саратовцев","c":[46.00917,51.55917],"tags":["Некрополь","Память"],"img":"NIVavilov Voskresenskoe bust.jpg","text":["Воскресенское кладбище — старинный некрополь Саратова.","Здесь похоронен Николай Чернышевский, над могилой которого стоит стеклянная часовня.","А у входа — памятник Николаю Вавилову: точное место его захоронения в общей могиле неизвестно до сих пор."],"au":{"t":[0.0,2.9,7.61,13.99],"d":21.17,"v":"069f7be06d"}},{"id":"tabakov","cat":"people","e":"🎬","name":"Памятник Олегу Табакову","short":"Саратовский мальчик с Театральной","c":[46.03228,51.53253],"tags":["Актёр","Личность"],"img":null,"text":["Олег Табаков родился в Саратове в 1935 году, в семье врачей.","Актёром его сделал драмкружок «Молодая гвардия» во Дворце пионеров — в том самом здании, возле которого стоит памятник.","Рядом с бронзовым актёром — кот Матроскин, который говорит его голосом."],"au":{"t":[0.0,2.81,9.02,17.62],"d":23.06,"v":"a7168108bd"}},{"id":"yankovsky","cat":"people","e":"🎞️","name":"Памятник Олегу Янковскому","short":"Тот самый Мюнхгаузен","c":[46.00299,51.53397],"tags":["Актёр","Сквер"],"img":null,"text":["Олег Янковский окончил Саратовское театральное училище и восемь лет служил в саратовском театре драмы.","Отсюда режиссёр Марк Захаров увёз его в Москву.","Сквер у театра, где стоит памятник, теперь носит его имя."],"au":{"t":[0.0,3.07,10.15,14.35],"d":19.61,"v":"9a0d3df5b7"}},{"id":"semenov","cat":"people","e":"⚗️","name":"Бюст Николая Семёнова","short":"Нобелевский лауреат из Саратова","c":[46.00888,51.53485],"tags":["Нобелевская премия","Учёный"],"img":null,"text":["Николай Семёнов родился в Саратове в 1896 году.","В 1956 году он получил Нобелевскую премию по химии за теорию цепных реакций — и до сих пор остаётся единственным советским химиком с этой наградой."],"au":{"t":[0.0,2.93,8.4],"d":19.03,"v":"7e23341899"}},{"id":"yablochkov","cat":"people","e":"💡","name":"Бюст Павла Яблочкова","short":"Изобретатель «русского света»","c":[46.00862,51.53565],"tags":["Изобретатель","Электричество"],"img":null,"text":["Павел Яблочков, уроженец Саратовской губернии, учился в саратовской гимназии.","Его дуговая лампа — «свеча Яблочкова» — в 1870-х годах осветила улицы Парижа и Лондона, и Европа назвала её «русским светом».","Последние месяцы жизни изобретатель провёл в Саратове, где и умер в 1894 году."],"au":{"t":[0.0,2.83,9.02,19.68],"d":27.1,"v":"f205327b20"}},{"id":"savin","cat":"people","e":"⚔️","name":"Последний солдат Наполеона","short":"Легенда о Жане-Батисте Савене","c":[46.02428,51.53163],"tags":["Легенда","1812"],"img":null,"text":["Мемориальная доска на этом доме рассказывает одну из самых удивительных саратовских легенд.","Здесь жил учитель французского Николай Савин — он же, по его словам, Жан-Батист Савен, офицер наполеоновской армии, попавший в плен в 1812 году.","Он умер в Саратове в 1894 году и, если верить его рассказам, прожил сто двадцать шесть лет.","Историки сомневаются в цифрах, но не в обаянии этой истории."],"au":{"t":[0.0,3.0,9.26,20.33,28.32],"d":33.36,"v":"8707a75d09"}},{"id":"raskova_mon","cat":"people","e":"✈️","name":"Памятник Марине Расковой","short":"Штурман и командир","c":[46.023718,51.565416],"tags":["1968","Авиация"],"img":"Памятник герою Советского союза Расковой М.М (1).jpg","text":["Марина Раскова — лётчица, штурман, Герой Советского Союза.","Осенью 1941 года она сформировала под Саратовом три женских авиаполка и сама возглавила один из них.","Раскова погибла в январе 1943 года в авиакатастрофе в Саратовской области; памятник ей открыли в День Победы 1968 года."],"au":{"t":[0.0,2.86,7.99,16.42],"d":26.83,"v":"2bb9e8af95"}},{"id":"ogni","cat":"mon","e":"💐","name":"«Огней так много золотых»","short":"Влюблённый с букетом","c":[46.02575,51.531833],"tags":["Памятник","Песня"],"img":null,"text":["Парень с букетом, который ждёт под часами, — герой песни «Огней так много золотых на улицах Саратова».","Песня прозвучала в фильме «Дело было в Пенькове» и стала неофициальным гимном города.","Считается, что если потереть букет, в любви обязательно повезёт."],"au":{"t":[0.0,2.9,10.42,16.56],"d":22.03,"v":"f5e233d8ad"}},{"id":"garmoshka","cat":"mon","e":"🪗","name":"Памятник саратовской гармошке","short":"Гармонь с колокольчиками","c":[46.032067,51.530519],"tags":["Памятник","Символ города"],"img":null,"text":["Саратовскую гармошку не спутаешь ни с какой другой: у неё звонкий голос и два колокольчика на корпусе.","Их делали в городе с середины девятнадцатого века, и «саратовская с колокольчиками» разошлась по всей России.","Бронзовый гармонист играет прямо посреди проспекта."],"au":{"t":[0.0,3.07,9.94,17.64],"d":21.79,"v":"f89d3d385e"}},{"id":"teacher","cat":"mon","e":"👩‍🏫","name":"Памятник первой учительнице","short":"Первый в России","c":[46.0475,51.53083],"tags":["Памятник","Сквер"],"img":"Учительница первая моя скульптор Волнухин СМ.jpg","text":["Это первый в России памятник первой учительнице.","Молодая учительница идёт на урок вместе со своими первоклассниками.","Вокруг разбит маленький уютный сквер, куда выпускники приходят с цветами."],"au":{"t":[0.0,3.12,7.22,12.53],"d":18.36,"v":"0ecfe4a61e"}},{"id":"yungi","cat":"mon","e":"⚓","name":"Памятник соловецким юнгам","short":"Мальчишки Северного флота","c":[46.037581,51.528499],"tags":["2002","Память"],"img":"Юным морякам саратовцам соловецкой школы юнг.jpg","text":["Этот памятник посвящён саратовским мальчишкам, которые в годы войны ушли в Соловецкую школу юнг Северного флота.","Многим из них было по пятнадцать-шестнадцать лет.","Памятник открыли в 2002 году у входа в «Липки»."],"au":{"t":[0.0,2.95,10.78,14.64],"d":19.44,"v":"042510b3e9"}},{"id":"heart","cat":"mon","e":"❤️","name":"«Сердце губернии»","short":"Знак центра области","c":[46.03296,51.5347],"tags":["Памятник","Символ"],"img":null,"text":["Знак «Сердце губернии» отмечает символический центр Саратовской области.","Здесь любят фотографироваться и загадывать желания, встав в самую середину."],"au":{"t":[0.0,2.38,8.45],"d":14.23,"v":"8b21886554"}},{"id":"tram","cat":"event","e":"🚋","name":"1908: первый трамвай","short":"Памятник саратовскому трамваю","c":[46.03866,51.52936],"tags":["1908","Событие","Транспорт"],"img":null,"text":["В октябре 1908 года по Саратову пошёл электрический трамвай, сменивший конку.","Строила его бельгийская компания, и первые вагоны тоже были бельгийскими.","Саратовский трамвай работает до сих пор, а его маршруты номер три и девять горожане называют просто «тройкой» и «девяткой»."],"au":{"t":[0.0,3.79,10.49,16.39],"d":25.34,"v":"3e46db9d28"}},{"id":"vodoprovodchik","cat":"mon","e":"🔧","name":"Памятник водопроводчику","short":"Бронзовый мастер","c":[46.0232,51.52219],"tags":["Памятник","Городская скульптура"],"img":null,"text":["Маленькая городская скульптура — водопроводчик за работой.","Саратовский водопровод — один из старейших в Поволжье: вода по трубам пришла в город ещё в 1870-х годах, а до того её возили бочками с Волги."],"au":{"t":[0.0,2.83,7.51],"d":17.76,"v":"9c8be8baba"}},{"id":"gorodovoy","cat":"mon","e":"👮","name":"Памятник городовому","short":"Страж старого Саратова","c":[46.04636,51.52629],"tags":["Памятник","Городская скульптура"],"img":null,"text":["Бронзовый городовой с шашкой и свистком несёт службу у набережной, как сто с лишним лет назад.","В дореволюционном Саратове постовой знал в лицо всех жителей своего квартала."],"au":{"t":[0.0,2.64,9.36],"d":14.74,"v":"55fd0aada6"}},{"id":"student","cat":"mon","e":"🎒","name":"Памятник студенту","short":"Вечный студент","c":[46.0402,51.5384],"tags":["Памятник","Городская скульптура"],"img":null,"text":["Саратов — город студенческий: здесь больше десятка вузов.","Бронзовый студент стоит у экономического института, и перед сессией к нему приходят на удачу."],"au":{"t":[0.0,2.47,7.34],"d":14.06,"v":"53b1e0307c"}},{"id":"krasnodon","cat":"mon","e":"🌟","name":"Сквер героев Краснодона","short":"На месте исчезнувшего храма","c":[46.045633,51.539063],"tags":["Сквер","Память"],"img":null,"text":["Памятник посвящён подпольщикам «Молодой гвардии».","У сквера двойная память: до тридцатых годов здесь стоял Ново-Никольский храм «на горах».","Его фундамент скрыт под дорожками, а памятник поставлен на месте алтаря."],"au":{"t":[0.0,3.02,7.39,13.92],"d":19.51,"v":"8c9522b4ab"}},{"id":"kirill","cat":"mon","e":"🔤","name":"Памятник Кириллу и Мефодию","short":"Создатели славянской азбуки","c":[46.0105,51.538972],"tags":["Памятник","Университет"],"img":null,"text":["Святые братья Кирилл и Мефодий, создатели славянской азбуки, стоят перед одним из корпусов университета.","Каждый год 24 мая, в День славянской письменности, здесь собираются студенты и преподаватели."],"au":{"t":[0.0,3.12,10.94],"d":18.46,"v":"6b42b56802"}},{"id":"det_park","cat":"park","e":"🎠","name":"Детский парк","short":"На месте Полтавской площади","c":[46.00742,51.53185],"tags":["Парк","6 гектаров"],"img":"Детский парк Ворота с ул Пугачёва вид на аллею Саратов.jpg","text":["Детский парк — третий по возрасту большой парк Саратова.","Он вырос на месте старой Полтавской площади, где до тридцатых годов стоял огромный Княже-Владимирский собор.","Собор разрушили, а на его месте зашумели аллеи и закружились карусели."],"au":{"t":[0.0,2.23,6.94,14.33],"d":20.11,"v":"1e9b4caee7"}},{"id":"kumyska","cat":"spring","e":"🌲","name":"Кумысная поляна","short":"Лес над городом · 4 400 га","c":[45.88,51.55],"z":13.6,"tags":["Природный парк","1991"],"img":"Kumysnaya Polyana Smirnovskoe.jpg","text":["Кумысная поляна — огромный лесной парк на плато над Саратовом.","В девятнадцатом веке здесь держали кобылиц и лечили горожан кумысом — отсюда и название.","Сегодня это больше четырёх тысяч гектаров дубрав, оврагов и полян, десятки родников и любимое место лыжников и велосипедистов."],"au":{"t":[0.0,2.47,7.34,14.14],"d":23.11,"v":"f8f4bb3ae4"}},{"id":"malinovy","cat":"spring","e":"💧","name":"Малиновый родник","short":"Самый известный на Кумыске","c":[45.88643,51.55566],"z":15.2,"tags":["Родник","Кумысная поляна"],"img":null,"text":["Малиновый родник бьёт в глубоком лесном овраге на Кумысной поляне.","О его названии спорят: то ли из-за зарослей дикой малины вокруг, то ли из-за «малинового» — мягкого и чистого — вкуса воды.","Вода здесь холодная круглый год, и саратовцы приезжают за ней с канистрами."],"au":{"t":[0.0,2.42,7.37,15.98],"d":21.72,"v":"41216293df"}},{"id":"serebryany","cat":"spring","e":"💧","name":"Серебряный родник","short":"Источник на севере города","c":[45.93664,51.58098],"z":15.2,"tags":["Родник"],"img":null,"text":["Серебряный родник — один из самых посещаемых источников в северной части города.","По народному поверью, вода в нём долго не портится, будто настояна на серебре."],"au":{"t":[0.0,2.54,8.69],"d":14.26,"v":"0f6a5598c3"}},{"id":"alexievsky","cat":"spring","e":"⛲","name":"Алексиевский монастырь и источник","short":"Обитель у святого ключа","c":[45.97517,51.55941],"z":15.6,"tags":["Родник","Монастырь"],"img":"Saint Alexius monastery (Saratov).JPG","text":["Свято-Алексиевский женский монастырь вырос вокруг родника на бывшей архиерейской даче.","Источник освящён, над ним устроена часовня, а рядом — купель.","Это тихий, утопающий в цветах уголок, где трудно поверить, что вокруг — миллионный город."],"au":{"t":[0.0,3.46,9.41,14.83],"d":22.08,"v":"d75478b501"}},{"id":"andreevsky","cat":"spring","e":"💧","name":"Андреевский родник","short":"У Андреевских прудов","c":[45.9159,51.57079],"z":15.2,"tags":["Родник","Кумысная поляна"],"img":null,"text":["Андреевский родник питает каскад лесных прудов на склоне Кумысной поляны.","Сюда ведёт одна из самых живописных пешеходных троп — от Девятой Дачной вверх, через дубраву."],"au":{"t":[0.0,2.62,8.21],"d":15.19,"v":"e0dd228d48"}},{"id":"tatarsky","cat":"spring","e":"💧","name":"Татарский родник","short":"Лесной источник","c":[45.91387,51.5575],"z":15.2,"tags":["Родник","Кумысная поляна"],"img":null,"text":["Татарский родник — ещё один источник Кумысной поляны, спрятанный в лесном овраге.","На плато и его склонах насчитывают несколько десятков родников, и у каждого есть свои преданные поклонники."],"au":{"t":[0.0,2.38,8.74],"d":16.22,"v":"af1d644af5"}},{"id":"bogatyrsky","cat":"spring","e":"💧","name":"Богатырский родник","short":"Сила лесной воды","c":[45.90328,51.55295],"z":15.2,"tags":["Родник","Кумысная поляна"],"img":null,"text":["Богатырский родник — популярная цель лесных прогулок по Кумысной поляне.","Говорят, кто напьётся из него после подъёма в гору, у того прибавится сил ровно на обратную дорогу."],"au":{"t":[0.0,2.47,7.94],"d":14.95,"v":"f609aee404"}},{"id":"glebovrag","cat":"spring","e":"🏞️","name":"Глебучев овраг","short":"Шрам старого города","c":[46.0533,51.5333],"tags":["Овраг","История"],"img":"Glebuchev ravine 1892.jpg","text":["Глебучев овраг тянется через весь старый Саратов на несколько километров.","В семнадцатом веке его называли «Воровским бараком» — в зарослях прятался лихой люд.","Позже склоны оврага облепили домишки бедноты, и этот особый мир не раз описывали саратовские писатели."],"au":{"t":[0.0,2.59,8.11,14.4],"d":21.89,"v":"fe310a28a6"}},{"id":"sokolovaya","cat":"event","e":"🔥","name":"1774: Пугачёв на Соколовой горе","short":"Пушки над городом","c":[46.0581,51.5428],"z":15.2,"tags":["1774","Событие","Пугачёв"],"img":"Views of Saratov from Volga River (July 2025) - 0 1.jpg","text":["В августе 1774 года на Соколовой горе стояли пушки Емельяна Пугачёва.","Отсюда повстанцы обстреляли город, и Саратов был взят за один день.","Пугачёв пробыл здесь всего три дня: раздал народу казённый хлеб и соль, привёл жителей к присяге и ушёл вниз по Волге — навстречу своему разгрому."],"au":{"t":[0.0,4.8,11.66,16.9],"d":26.4,"v":"8ab6ca14e4"}},{"id":"pokrov_church","cat":"temple","e":"⛪","name":"Покровская церковь","short":"Храм «на горах» · 1883","c":[46.035194,51.540333],"tags":["1883","Храм"],"img":"Church of the Intercession of Our Lady in Saratov, Russia.jpg","text":["Покровскую церковь построил в 1876–1883 годах архитектор Алексей Салько.","В тридцатые годы храм закрыли, колокольню снесли, а внутри устроили общежитие и художественные мастерские.","Верующим его вернули в 1992 году, колокольню отстроили заново — и теперь она снова видна издалека."],"au":{"t":[0.0,2.5,10.63,18.24],"d":26.66,"v":"41a052a77f"}},{"id":"catholic","cat":"temple","e":"✝️","name":"Собор Петра и Павла","short":"Католический собор","c":[46.04472,51.5275],"tags":["Храм","Католики"],"img":"Saratov sobor petra i pavla.JPG","text":["Современный католический собор Петра и Павла — напоминание о том, что Саратов был центром огромной католической епархии.","Её прихожанами были в основном немцы Поволжья.","Старый собор Святого Климента стоял на Немецкой улице; в советские годы его перестроили в кинотеатр «Пионер»."],"au":{"t":[0.0,2.83,11.4,15.62],"d":23.78,"v":"2f19002e44"}},{"id":"mosque","cat":"temple","e":"🕌","name":"Соборная мечеть","short":"Минареты над Татарской улицей","c":[46.038083,51.537417],"tags":["Храм","Ислам"],"img":"Saratov mechet.JPG","text":["Соборная мечеть — главный мусульманский храм Саратова.","Татарская община живёт в городе с первых лет его истории, а нынешнее здание с высокими минаретами возродили в двухтысячные годы на месте старой мечети."],"au":{"t":[0.0,2.52,7.2],"d":16.94,"v":"efe5cebd5b"}},{"id":"duhososh","cat":"temple","e":"⛪","name":"Духосошественский собор","short":"Храм над Глебучевым оврагом","c":[46.056136,51.536206],"tags":["XIX век","Храм"],"img":"Саратов Храм Сошествия Святого Духа (вид с севера).jpg","text":["Храм Сошествия Святого Духа стоит на высоком краю Глебучева оврага.","Он не закрывался надолго даже в советские годы, а с 2001 по 2014 год был кафедральным собором епархии."],"au":{"t":[0.0,2.86,8.16],"d":16.66,"v":"b0b2e5d3f6"}},{"id":"spas_mon","cat":"temple","e":"☦️","name":"Спасо-Преображенский монастырь","short":"Основан в 1680 году","c":[45.99361,51.55611],"tags":["1680","Монастырь"],"img":"Саратовский Спасо-Преображенский монастырь 3 (1891).jpg","text":["Спасо-Преображенский мужской монастырь основан в 1680 году и считается одним из старейших в Поволжье.","В советское время на его территории размещалось военное училище, а монашеская жизнь возобновилась уже в наше время."],"au":{"t":[0.0,3.07,11.02],"d":18.72,"v":"b444be2630"}},{"id":"nevsky","cat":"event","e":"🏟️","name":"Исчезнувший собор Александра Невского","short":"Сегодня здесь стадион «Динамо»","c":[46.0357,51.5287],"tags":["1826","Событие","Утрачено"],"img":"Aleksandro-nevskiy sobor saratov.jpg","text":["На месте стадиона «Динамо» сто лет возвышался главный собор Саратова — Александро-Невский.","Его заложили в 1815 году в память о саратовских ополченцах, сражавшихся с Наполеоном, по проекту знаменитого зодчего Василия Стасова.","В тридцатые годы собор разобрали.","Сад «Липки» когда-то был его соборным бульваром."],"au":{"t":[0.0,3.6,10.78,21.05,24.5],"d":29.04,"v":"0b7a00d535"}},{"id":"museum_sq","cat":"event","e":"🏰","name":"1674: рождение правобережного Саратова","short":"Музейная площадь","c":[46.05528,51.52833],"tags":["1674","Событие","Основание"],"img":"Музейная площадь Саратов.jpg","text":["Саратов основали в 1590 году как сторожевую крепость на Волге — и за первые сто лет город трижды менял место.","В 1674 году по царскому указу его перенесли с левого берега сюда, на правый.","Именно на этой площади стояла деревянная крепость, а Троицкий собор — её прямой наследник."],"au":{"t":[0.0,5.4,13.92,21.05],"d":27.91,"v":"29bebddf5d"}},{"id":"left_saratov","cat":"event","e":"🧭","name":"1617: Саратов на левом берегу","short":"Город, который переехал","c":[46.2169,51.5186],"z":13.6,"tags":["1617","Событие","Основание"],"img":null,"text":["Мало кто знает, что больше полувека Саратов стоял на левом, луговом берегу Волги — примерно здесь, у устья речки Саратовки.","Сюда город перенесли после пожара, уничтожившего первую крепость.","Мимо левобережного Саратова проплывал немецкий путешественник Адам Олеарий, оставивший его первое описание и рисунок."],"au":{"t":[0.0,4.39,12.98,18.41],"d":26.66,"v":"4826f236dd"}},{"id":"dubki","cat":"event","e":"🛩️","name":"1955: первый полёт Гагарина","short":"Аэродром Дубки","c":[46.05833,51.65],"z":13.6,"tags":["1955","Событие","Гагарин"],"img":null,"text":["На аэродроме Дубки летом 1955 года курсант саратовского аэроклуба Юрий Гагарин впервые самостоятельно поднял в воздух самолёт Як-18.","Инструктор Дмитрий Мартьянов запомнил его как очень упорного ученика.","Аэроклуб, который теперь носит имя Гагарина, работает здесь до сих пор."],"au":{"t":[0.0,4.68,15.6,20.9],"d":26.86,"v":"83260a43a6"}},{"id":"gas","cat":"event","e":"🔥","name":"1946: газопровод Саратов — Москва","short":"Первая газовая магистраль страны","c":[45.923275,51.626691],"z":14.2,"tags":["1946","Событие","Промышленность"],"img":null,"text":["На этом месте, у посёлка Елшанка, в годы войны ударил фонтан природного газа.","Отсюда проложили первый в стране магистральный газопровод — Саратов — Москва длиной более восьмисот километров.","Летом 1946 года саратовский газ пришёл на московские кухни, и с этого началась газовая отрасль России."],"au":{"t":[0.0,4.99,11.09,18.53],"d":27.12,"v":"9f563c17f5"}},{"id":"engels_city","cat":"engels","e":"🐂","name":"Энгельс: бык-солевоз","short":"Покровская слобода · 1747","c":[46.12681,51.48552],"z":16.2,"tags":["1747","Энгельс","Символ города"],"img":null,"text":["Добро пожаловать на левый берег, в город Энгельс.","Он начался в 1747 году с Покровской слободы: сюда по указу императрицы Елизаветы свозили соль с озера Эльтон.","Соль везли на волах украинские чумаки — поэтому символом города стал бык с солонкой на спине.","До 1931 года город назывался Покровском, и многие жители зовут его так до сих пор."],"au":{"t":[0.0,3.05,7.15,15.74,22.25],"d":29.4,"v":"fa2762f455"}},{"id":"engels_museum","cat":"engels","e":"🏺","name":"Энгельсский краеведческий музей","short":"История Покровска","c":[46.12027,51.5029],"z":16.4,"tags":["Музей","Энгельс"],"img":null,"text":["Краеведческий музей Энгельса рассказывает историю Покровска — от соляного городка чумаков до столицы немецкой автономии.","В его собрании — большая коллекция картин Якова Вебера, самого известного художника немецкого Поволжья."],"au":{"t":[0.0,3.19,11.38],"d":18.98,"v":"ea1f23381d"}},{"id":"kassil","cat":"engels","e":"📗","name":"Дом-музей Льва Кассиля","short":"Родина Швамбрании","c":[46.12205,51.4969],"z":16.6,"tags":["1905","Писатель","Энгельс"],"img":null,"text":["В этом доме прошло детство писателя Льва Кассиля — он родился в Покровской слободе в 1905 году.","Здесь он с младшим братом придумал страну Швамбранию, о которой потом написал знаменитую повесть «Кондуит и Швамбрания».","В музее можно увидеть, как выглядела эта выдуманная страна."],"au":{"t":[0.0,2.98,10.46,19.2],"d":24.24,"v":"65fddc471f"}},{"id":"germans","cat":"engels","e":"🕊️","name":"1941: депортация немцев Поволжья","short":"Памятник жертвам репрессий","c":[46.125314,51.50116],"z":16.4,"tags":["1941","Событие","Энгельс"],"img":null,"text":["С 1920-х годов Энгельс был столицей Автономной республики немцев Поволжья.","Здесь работали немецкий театр, издательство и педагогический институт.","Двадцать восьмого августа 1941 года вышел указ о переселении, и сотни тысяч человек за несколько недель выслали в Сибирь и Казахстан.","Памятник российским немцам — жертвам репрессий открыли в 2011 году."],"au":{"t":[0.0,4.85,11.62,17.47,27.34],"d":33.46,"v":"cbc4f2e878"}},{"id":"pered_poletom","cat":"engels","e":"🤝","name":"«Перед полётом»","short":"Гагарин и Королёв на набережной","c":[46.12178,51.50411],"z":16.4,"tags":["2017","Памятник","Энгельс"],"img":null,"text":["На энгельсской набережной беседуют двое — Юрий Гагарин и главный конструктор Сергей Королёв.","Памятник «Перед полётом» открыли в 2017 году.","Гагарин приземлился в Энгельсском районе, и сразу после посадки его привезли на энгельсский аэродром — отсюда он доложил в Москву о выполнении задания."],"au":{"t":[0.0,2.14,8.45,13.66],"d":23.93,"v":"faedd3fcc6"}},{"id":"raskova_engels","cat":"engels","e":"🌙","name":"1941: «Ночные ведьмы»","short":"Женские авиаполки Расковой","c":[46.15962,51.48037],"z":15.8,"tags":["1941","Событие","Энгельс"],"img":null,"text":["Осенью 1941 года в Энгельсе Марина Раскова формировала три женских авиационных полка — истребительный, бомбардировочный и ночной бомбардировочный.","Последний немцы прозвали «ночными ведьмами»: лётчицы на фанерных бипланах По-2 бесшумно бомбили врага по ночам.","Двадцать три девушки из этого полка стали Героями Советского Союза."],"au":{"t":[0.0,4.08,14.98,22.8],"d":27.82,"v":"562e731b5e"}},{"id":"engels_sobor","cat":"engels","e":"⛪","name":"Троицкий собор Энгельса","short":"Кафедральный собор Покровска","c":[46.127333,51.498861],"z":16.4,"tags":["Храм","Энгельс"],"img":"Engels Holy Trinity Cathedral in Sept 2017.jpg","text":["Свято-Троицкий собор — главный храм Энгельса и кафедральный собор Покровской епархии.","Он стоит в старой части города, среди купеческих особняков бывшей Покровской слободы."],"au":{"t":[0.0,2.88,9.29],"d":15.65,"v":"5159884c64"}},{"id":"operetta","cat":"engels","e":"🎶","name":"Театр оперетты","short":"Музыкальный театр на левом берегу","c":[46.12139,51.5],"z":16.4,"tags":["Театр","Энгельс"],"img":"Театр Оперетты 2023.jpg","text":["Саратовский областной театр оперетты работает не в Саратове, а в Энгельсе.","Это один из немногих театров оперетты в Поволжье, и на премьеры сюда ездят через мост с правого берега."],"au":{"t":[0.0,2.57,8.02],"d":15.19,"v":"bce97727aa"}},{"id":"pokrov_park","cat":"engels","e":"🌳","name":"Парк «Покровский»","short":"Главный парк Энгельса","c":[46.12345,51.50248],"z":16.2,"tags":["Парк","Энгельс"],"img":null,"text":["Городской парк «Покровский» — зелёное сердце Энгельса у самой Волги.","От него начинается набережная с видом на саратовский берег: оттуда весь Саратов с его холмами виден как на открытке."],"au":{"t":[0.0,2.38,8.11],"d":15.72,"v":"3928bf5457"}},{"id":"aviation_museum","cat":"engels","e":"🛫","name":"Музей дальней авиации","short":"Крылатые гиганты","c":[46.18917,51.47527],"z":14.8,"tags":["Музей","Авиация","Энгельс"],"img":null,"text":["Энгельс — город авиаторов: лётная школа появилась здесь ещё в начале тридцатых годов.","В музее дальней авиации под открытым небом собраны самолёты разных поколений — от поршневых машин до сверхзвуковых ракетоносцев."],"au":{"t":[0.0,3.02,9.38],"d":18.05,"v":"f6b66660e3"}},{"id":"icebreaker","cat":"engels","e":"🚢","name":"«Саратовский ледокол»","short":"Пароход 1895 года","c":[46.07833,51.506643],"z":15.2,"tags":["1895","Волга","История"],"img":"IcebreakerSaratov.jpg","text":["«Саратовский ледокол» построили в Англии в 1895 году по заказу Рязанско-Уральской железной дороги.","Пока через Волгу не было моста, он зимой проводил сквозь льды паромы с железнодорожными вагонами.","Ледокол прошёл две войны, строил Волжскую ГЭС и мосты, а его корпус до сих пор лежит в затоне у энгельсского берега."],"au":{"t":[0.0,2.62,10.58,17.04],"d":24.91,"v":"ed4d25c4e7"}},{"id":"lukomorye","cat":"park","e":"🧙","name":"Парк «Лукоморье»","short":"Сказка у городского парка","c":[45.99916,51.51665],"tags":["Парк","Для детей"],"img":null,"text":["«Лукоморье» — небольшой сказочный парк по соседству с Городским парком.","Среди деревьев здесь прячутся деревянные герои русских сказок, а в прудах плавают рыбы и утки.","Его любят за тишину: сюда приходят гулять с детьми и кормить птиц."],"au":{"t":[0.0,2.38,7.7,14.57],"d":19.8,"v":"a48e075931"}},{"id":"botsad","cat":"park","e":"🌺","name":"Ботанический сад университета","short":"Живая коллекция растений","c":[46.00815,51.5663],"tags":["Сад","Наука"],"img":null,"text":["Ботанический сад Саратовского университета — зелёная лаборатория под открытым небом.","Здесь собраны сотни видов растений со всего света — от степных ковылей Поволжья до редких деревьев Дальнего Востока.","Весной в сад приходят смотреть, как цветут сирень, магнолии и тюльпаны."],"z":15.6,"au":{"t":[0.0,3.48,9.72,17.54],"d":23.5,"v":"bb3c715817"}},{"id":"limonary","cat":"park","e":"🍋","name":"Саратовский лимонарий","short":"Лимоны на Волге","c":[46.06668,51.55632],"tags":["Оранжерея","Сад"],"img":null,"text":["В Саратовском лимонарии под стеклянными крышами зреют лимоны, апельсины и мандарины.","Зимой, когда за окном снег и мороз, здесь пахнет цитрусовым цветом.","Саженцы отсюда разъезжаются по подоконникам всей страны."],"z":15.8,"au":{"t":[0.0,2.76,9.12,14.9],"d":19.42,"v":"e3829ffaf0"}},{"id":"tulaykov","cat":"park","e":"🌾","name":"Сквер Тулайкова","short":"Память об академике-агрономе","c":[45.99852,51.57147],"tags":["Сквер","Учёный"],"img":null,"text":["Сквер носит имя академика Николая Тулайкова — учёного, который учил земледельцев Поволжья побеждать засуху.","Он возглавлял саратовский институт зернового хозяйства и был одним из самых известных агрономов страны.","В 1937 году Тулайкова арестовали, и он погиб в заключении; доброе имя вернули ему уже после смерти."],"z":15.8,"au":{"t":[0.0,2.54,10.3,17.3],"d":25.99,"v":"44323fa5c0"}},{"id":"petr_sq","cat":"park","e":"👑","name":"Сквер Петра Первого","short":"Царь на Музейной площади","c":[46.05494,51.52698],"tags":["Сквер","Памятник"],"img":null,"text":["Пётр Первый бывал в Саратове дважды — в 1695 году по пути к Азову и в 1722 году, отправляясь в Персидский поход.","По преданию, царь поднялся на Соколовую гору и пожаловал городу все земли, какие видны с её вершины.","Бронзовый Пётр стоит у Волги, там, где начинался старый город."],"au":{"t":[0.0,2.74,12.86,20.06],"d":25.3,"v":"26b523fe23"}},{"id":"bogolubov_sq","cat":"park","e":"🖼️","name":"Сквер Боголюбова","short":"У Театральной площади","c":[46.03274,51.53375],"tags":["Сквер","Художник"],"img":null,"text":["Уютный сквер у Театральной площади назван в честь художника Алексея Боголюбова.","Внук Радищева и знаменитый маринист, он подарил Саратову музей и завещал городу свою коллекцию и состояние."],"au":{"t":[0.0,2.54,8.33],"d":16.32,"v":"40c00ff890"}},{"id":"babushkin","cat":"park","e":"🪜","name":"Бабушкин взвоз","short":"Старинный спуск к Волге","c":[46.03897,51.52499],"tags":["Сквер","Старый город"],"img":null,"text":["Взвозами в волжских городах называли улицы, по которым с пристаней поднимали — «взвозили» — товары.","Бабушкин взвоз получил имя по фамилии домовладельца, жившего здесь в старину.","Сегодня это тихая зелёная улица-сквер, которая выводит прямо на набережную."],"au":{"t":[0.0,2.38,9.74,15.72],"d":21.77,"v":"20a8e1b7b8"}},{"id":"nikitin_sq","cat":"park","e":"🤹","name":"Сквер братьев Никитиных","short":"Перед цирком","c":[46.0192,51.53369],"tags":["Сквер","Цирк"],"img":null,"text":["В сквере у цирка стоят бронзовые братья Никитины — Дмитрий, Аким и Пётр.","Сыновья крепостного шарманщика, они первыми в России создали цирк без иностранных антрепренёров.","Перед представлениями сквер наполняется детьми."],"au":{"t":[0.0,3.02,8.86,15.77],"d":19.7,"v":"a24c2fb2c1"}},{"id":"sq1905","cat":"park","e":"✊","name":"Сквер борцов революции","short":"Площадь 1905 года","c":[46.00433,51.52018],"tags":["Сквер","История"],"img":null,"text":["Сквер и площадь напоминают о событиях 1905 года, когда по Саратову прокатились стачки и демонстрации.","В центре стоит монумент борцам революции — характерный памятник советской эпохи."],"au":{"t":[0.0,2.95,11.26],"d":17.38,"v":"0b32160c73"}},{"id":"rotonda","cat":"park","e":"🏛️","name":"Ротонда на набережной","short":"Белая беседка над Волгой","c":[46.03975,51.52284],"tags":["Набережная","Символ"],"img":null,"text":["Белая ротонда с колоннами — одна из визитных карточек саратовской набережной.","Здесь фотографируются молодожёны, выпускники и все, кто впервые приехал в город.","Отсюда хорошо видно, как широко разливается Волга."],"au":{"t":[0.0,2.66,8.45,14.86],"d":19.27,"v":"5a497e9fc4"}},{"id":"beach","cat":"park","e":"🏖️","name":"Городской пляж","short":"Остров под мостом","c":[46.0756,51.51574],"tags":["Пляж","Волга"],"img":null,"text":["Городской пляж Саратова лежит на острове прямо под мостом через Волгу.","Попасть сюда можно пешком — по лестнице с моста.","В жаркий день здесь собирается, кажется, полгорода."],"z":15.4,"au":{"t":[0.0,2.26,7.22,11.33],"d":15.89,"v":"9cb8ffe869"}},{"id":"aviastroy","cat":"park","e":"🛩️","name":"Сквер Авиастроителей","short":"Память о крылатом заводе","c":[45.9431,51.5024],"tags":["Сквер","Авиация"],"img":null,"text":["Заводской район вырос вокруг Саратовского авиационного завода.","В годы войны его цеха горели под бомбёжками, но завод продолжал выпускать истребители Як.","После войны здесь строили пассажирские Як-40 и Як-42, на которых летала вся страна."],"z":15.8,"au":{"t":[0.0,2.95,7.73,14.4],"d":21.12,"v":"c1a79f2314"}},{"id":"druzhba","cat":"park","e":"⛲","name":"Сквер Дружбы народов","short":"Фонтан мира","c":[45.94827,51.50314],"tags":["Сквер","Фонтан"],"img":null,"text":["Сквер Дружбы народов — любимое место отдыха жителей Заводского района.","В 2015 году здесь открыли «Фонтан мира»."],"z":15.8,"au":{"t":[0.0,2.74,8.28],"d":13.13,"v":"4997dcaa8b"}},{"id":"pobeda_sq","cat":"park","e":"🎗️","name":"Сквер Победы","short":"Ленинский район · 1976","c":[45.9799,51.60696],"tags":["Сквер","Память"],"img":null,"text":["Сквер Победы заложили в 1976 году в Ленинском районе — самом большом районе Саратова.","Северная часть города выросла вокруг электронных и приборостроительных заводов."],"z":15.8,"au":{"t":[0.0,2.3,9.77],"d":15.46,"v":"b57e86751b"}},{"id":"territory","cat":"park","e":"🧒","name":"Аллея пионеров-героев","short":"Сквер «Территория детства»","c":[45.9702,51.59396],"tags":["Сквер","Память"],"img":null,"text":["В сквере у Центра детского творчества проходит аллея пионеров-героев.","Это мемориал ребятам, которые в годы войны сражались наравне со взрослыми — в партизанских отрядах и подполье."],"z":15.8,"au":{"t":[0.0,2.78,7.99],"d":15.62,"v":"5402a34a64"}},{"id":"gagarin_park","cat":"park","e":"🌠","name":"Парк имени Гагарина","short":"Юг Саратова","c":[45.89261,51.47847],"tags":["Парк","Гагарин"],"img":null,"text":["Парк имени Гагарина — зелёный остров на южной окраине Саратова.","В городе, где первый космонавт учился и впервые взлетел, его имя носят парк, набережная, университет и аэропорт."],"z":15.6,"au":{"t":[0.0,2.62,7.92],"d":16.92,"v":"7c89928893"}},{"id":"schnittke","cat":"culture","e":"🎼","name":"Филармония имени Шнитке","short":"Музыкальный дом с 1937 года","c":[46.03459,51.52713],"tags":["1937","Музыка"],"img":null,"text":["Саратовская филармония работает с 1937 года и носит имя композитора Альфреда Шнитке.","Шнитке родился в 1934 году на другом берегу Волги — в Энгельсе.","Его музыку знают по всему миру, а ещё — по десяткам кинофильмов."],"au":{"t":[0.0,3.17,10.75,16.8],"d":22.15,"v":"a2dba5ae02"}},{"id":"engels_sq","cat":"engels","e":"🧔","name":"Площадь Энгельса","short":"Почему Покровск стал Энгельсом","c":[46.13169,51.48312],"tags":["1931","Энгельс","Площадь"],"img":null,"text":["На главной площади города стоит памятник Фридриху Энгельсу.","Покровск переименовали в его честь в 1931 году, когда город был столицей республики немцев Поволжья.","Сам философ здесь никогда не бывал."],"z":16.2,"au":{"t":[0.0,2.47,7.18,15.46],"d":18.84,"v":"e5e4209971"}},{"id":"engels_nab","cat":"engels","e":"🌊","name":"Набережная Энгельса","short":"Вид на саратовский берег","c":[46.11787,51.5033],"tags":["Набережная","Энгельс"],"img":null,"text":["Набережная Энгельса носит имя генерала Рудченко и тянется вдоль Волги.","Отсюда открывается лучший вид на Саратов: мост, Соколовая гора и огни города отражаются в воде.","По вечерам здесь гуляет, кажется, весь Энгельс."],"z":16,"au":{"t":[0.0,2.76,8.18,15.36],"d":19.8,"v":"daaf10943d"}},{"id":"engels_beach","cat":"engels","e":"🏖️","name":"Пляж Энгельса","short":"Песок у самого центра","c":[46.10545,51.50365],"tags":["Пляж","Энгельс"],"img":null,"text":["Центральный пляж Энгельса — широкая полоса волжского песка совсем рядом с центром города.","Летом сюда приезжают и саратовцы — через мост всего несколько минут."],"z":15.6,"au":{"t":[0.0,2.38,8.76],"d":14.11,"v":"5e17e9d45e"}},{"id":"engels_detpark","cat":"engels","e":"🎡","name":"Детский парк Энгельса","short":"У Троицкого собора","c":[46.12704,51.49919],"tags":["Парк","Энгельс"],"img":null,"text":["Детский парк — тенистый уголок в старой части Энгельса, рядом с Троицким собором.","Вокруг сохранились купеческие дома бывшей Покровской слободы — с резными наличниками и узорной кирпичной кладкой."],"z":16.2,"au":{"t":[0.0,2.88,9.14],"d":17.02,"v":"228a55ef66"}},{"id":"parovoz","cat":"engels","e":"🚂","name":"Паровоз Л-1578","short":"Памятник железной дороге","c":[46.10286,51.48629],"tags":["2010","Энгельс","Транспорт"],"img":null,"text":["Паровоз поставили на вечную стоянку в 2010 году.","Железная дорога сделала из Покровской слободы город: в 1894 году отсюда пошли поезда на Уральск.","До постройки моста вагоны переправляли через Волгу на паромах, а зимой рельсы укладывали прямо по льду."],"z":16,"au":{"t":[0.0,3.84,8.47,16.66],"d":23.5,"v":"30037ff02b"}},{"id":"kassil_mon","cat":"engels","e":"📕","name":"Памятник Льву Кассилю","short":"Писатель в родном городе","c":[46.12416,51.49649],"tags":["Памятник","Энгельс"],"img":null,"text":["Бронзовый Лев Кассиль стоит в родном городе, неподалёку от дома, где прошло его детство.","Кассиль написал «Кондуит и Швамбранию», «Вратаря республики» и «Дорогие мои мальчишки» — книги, на которых выросло несколько поколений."],"z":16.4,"au":{"t":[0.0,2.74,9.14],"d":19.06,"v":"28291e306f"}},{"id":"heroes_engels","cat":"engels","e":"⭐","name":"Мемориал героям фронта и тыла","short":"Память о 1941–1945","c":[46.12605,51.50353],"tags":["Мемориал","Энгельс"],"img":null,"text":["Мемориал в парке у Волги посвящён жителям Энгельса — тем, кто воевал, и тем, кто работал в тылу.","В годы войны город принимал эвакуированные заводы и госпитали, а на его аэродроме готовили лётчиков для фронта."],"z":16.2,"au":{"t":[0.0,3.36,10.92],"d":18.53,"v":"6e660fed48"}},{"id":"tu22","cat":"engels","e":"🛩️","name":"Самолёт Ту-22","short":"Памятник в Лётном городке","c":[46.16191,51.47423],"tags":["Авиация","Энгельс"],"img":null,"text":["Сверхзвуковой Ту-22 на постаменте — памятник лётчикам Энгельса.","История авиации началась здесь в начале тридцатых годов, когда в степи за Покровском открыли школу военных лётчиков."],"z":15.8,"au":{"t":[0.0,2.78,8.45],"d":16.25,"v":"f797c3a13a"}},{"id":"dance","cat":"engels","e":"💃","name":"«Танцующая пара»","short":"Городская скульптура","c":[46.13399,51.47784],"tags":["Скульптура","Энгельс"],"img":null,"text":["Бронзовая пара кружится в танце посреди города.","Небольшие городские скульптуры в Энгельсе любят: на набережной и в скверах их уже больше десятка."],"z":16.4,"au":{"t":[0.0,2.5,6.36],"d":12.91,"v":"6d6a3259f1"}},{"id":"dub","cat":"engels","e":"🌳","name":"Дуб-великан","short":"Патриарх волжской поймы","c":[46.06848,51.4915],"tags":["Природа","Остров"],"img":null,"text":["На острове между Саратовом и Энгельсом растёт дуб-великан — одно из самых старых деревьев волжской поймы.","Когда-то дубравы покрывали все здешние острова."],"z":15.2,"au":{"t":[0.0,2.16,9.55],"d":13.68,"v":"43d14b1880"}},{"id":"engels_mosque","cat":"engels","e":"🕌","name":"Соборная мечеть Энгельса","short":"Храм мусульман левобережья","c":[46.1417,51.49496],"tags":["Храм","Энгельс"],"img":null,"text":["Соборная мечеть Энгельса — духовный центр мусульман левобережья.","Покровск с самого начала был многонациональным: здесь жили русские, украинцы, немцы, татары и казахи."],"z":16.2,"au":{"t":[0.0,3.07,8.26],"d":16.37,"v":"eae15ee36d"}},{"id":"trolza","cat":"engels","e":"🚎","name":"Троллейбусный завод","short":"Родина ЗиУ","c":[46.11833,51.46472],"tags":["1951","Энгельс","Промышленность"],"img":null,"text":["С 1951 года в Энгельсе делали троллейбусы — знаменитые ЗиУ, названные по старому имени завода: имени Урицкого.","Модель ЗиУ-9 стала самым массовым троллейбусом в мире: их выпустили более сорока тысяч.","Энгельсские троллейбусы работали в десятках стран."],"z":15.6,"au":{"t":[0.0,2.57,11.69,18.43],"d":22.37,"v":"8bb2dbb873"}},{"id":"ped_inst","cat":"engels","e":"🏫","name":"Немецкий педагогический институт","short":"Вуз исчезнувшей республики","c":[46.1302,51.4974],"tags":["1929–1941","Энгельс","История"],"img":null,"text":["В тридцатые годы здесь работал Немецкий государственный педагогический институт.","Он готовил учителей для школ республики немцев Поволжья и был главным её вузом.","Институт закрыли осенью 1941 года — вместе с самой республикой."],"z":16.4,"au":{"t":[0.0,3.7,9.48,15.34],"d":21.84,"v":"c52aec1023"}},{"id":"flight_school","cat":"engels","e":"🎖️","name":"Школа военных лётчиков","short":"С чего начинался авиагород","c":[46.1636,51.4795],"tags":["1930-е","Энгельс","Авиация"],"img":null,"text":["Военную школу лётчиков основали под Энгельсом в начале тридцатых годов.","Через неё прошли тысячи пилотов, а в годы войны здесь формировались женские авиаполки Марины Расковой.","С тех пор Энгельс называют городом авиаторов."],"z":15.8,"au":{"t":[0.0,3.0,8.38,15.53],"d":19.63,"v":"778ae544c4"}}];
